// Invented fixture for exercising six existing records guard migrations.
import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import {createHash} from 'node:crypto';
import {describeParitySource,parityAstHash,parityHash} from '../../scripts/qualify-parity.mjs';
import {analyzeRecordsFixtureSlice} from '../../scripts/parity-records-fixture-slice.mjs';
const sha=x=>createHash('sha256').update(x).digest('hex');
export function createRecordsSixFixture(){
 const root=fs.mkdtempSync(path.join(os.tmpdir(),'records-six-private-'));fs.writeFileSync(path.join(root,'package.json'),'{"type":"module"}');
 const selected=Array.from({length:6},(_,i)=>`test('case-${i+1}', async () => { const runtime = await setup(); assert.equal(runtime.store.status, 200); });`).join('\n');
 const baseline=["// @test-kind unproven: Invented local fixture for qualifier tooling.","import test from 'node:test'; import assert from 'node:assert/strict'; import { randomUUID } from 'node:crypto'; import { emptyState, Store, seed } from './sut.mjs';", "const ORG = 'invented'; const SETTINGS = { organizationId: ORG, users: [{ name: 'sample' }] }; const lookup = { type: 'reference' }; const text = { type: 'text' };", "function fixtureState() { const state = emptyState(); state.mappings = { label: text, owner: lookup }; return state; }", "async function setup() { const store = new Store({ state: fixtureState() }); await seed(store, SETTINGS); return { store }; }", "test('mutator-value', () => { SETTINGS.users[0].name = 'changed'; }); test('mutator-accessor', () => { Object.defineProperty(text, 'type', { get: () => 'text', enumerable: true, configurable: true }); });",selected,"test('uuid-sibling', () => { const id = randomUUID(); assert.ok(id); });"].join('\n');
 const proof={captures:[{runSha256:'1'.repeat(64),status:200},{runSha256:'2'.repeat(64),status:200}],facts:{status:200}};fs.writeFileSync(path.join(root,'proof.json'),JSON.stringify(proof));const priorProof={path:'proof.json',sha256:parityHash(fs.readFileSync(path.join(root,'proof.json'))),mode:'reproduced-native',capturePointers:['/captures/0/runSha256','/captures/1/runSha256'],facts:[{id:'status',pointer:'/facts/status',sha256:parityHash(JSON.stringify(200)),replicatedPointers:['/captures/0/status','/captures/1/status']}]};
 const model=describeParitySource(baseline,'sample.test.mjs'),rows=model.registrations.filter(r=>r.title?.startsWith('case-'));if(rows.length!==6)throw Error('fixture-registration');
 const edits=[],guarantees=[];for(const row of rows){const descriptor={baselineId:row.id,repositoryRoot:'.',titleExpressionSha256:row.titleExpressionSha256,originalAssertions:row.assertions.map(a=>a.sha256),originalBodyAstSha256:parityAstHash(row.callback.body),sourceBindings:[],loopHeaders:[],proofs:[priorProof]};edits.push({position:row.callback.body.range[0]+1,text:` __paqParityBindings(import.meta.url, ${JSON.stringify([descriptor])}); `});edits.push({position:row.statement.range[0],text:'// @test-kind parity: Invented evidence fixture for tooling only.\n// @parity-evidence: Synthetic fixture, never platform evidence.\n'});guarantees.push({id:'fixture-'+row.title,reason:'Preserve the invented original assertion and its prior synthetic proof.',context:{reviewedBy:'tooling-author',authorResponsibility:true,summary:'Invented fixture; no platform or native behavior claim.'},proofs:[priorProof],tests:[{baselineId:row.id,titleExpressionSha256:row.titleExpressionSha256,assertions:row.assertions.map(a=>({sha256:a.sha256,factIds:['status']})),caseUniverse:{count:1,cases:[row.title],casesSha256:sha(JSON.stringify([row.title])),sourceBindings:[],ancestorLoops:[]}}]});}
 let current=baseline;for(const edit of edits.sort((a,b)=>b.position-a.position))current=current.slice(0,edit.position)+edit.text+current.slice(edit.position);current=`import { assertParityBindings as __paqParityBindings, assertParityBindingsFromSource as __paqParitySourceBindings } from '${new URL('../../scripts/qualify-parity.mjs', import.meta.url).href}';\n`+current+"\n// @test-kind tooling: Shared synthetic source guard.\ntest('parity source bindings 0000000000000000', () => { __paqParitySourceBindings(import.meta.url); });\n";
 fs.writeFileSync(path.join(root,'sample.test.mjs'),current);fs.writeFileSync(path.join(root,'sut.mjs'),"export function emptyState(){return {mappings:{}};} export class Store { constructor({state}) { this.state=structuredClone(state); this.status=200; } } export async function seed(store, settings) { if (!settings.organizationId) throw Error('missing'); }\n");
 const manifest={version:1,baseline:'a'.repeat(40),files:[{path:'sample.test.mjs',baselineSha256:parityHash(baseline),currentSha256:parityHash(current),importRoles:[{source:'./sut.mjs',role:'implementation-under-test',reviewedBy:'tooling-author',reason:'Invented fresh store runtime used by tooling fixture.'}],guarantees}]};
 const now=describeParitySource(current,'sample.test.mjs');const analysis=rows.map(row=>{const next=now.registrations.find(r=>r.titleExpressionSha256===row.titleExpressionSha256);return analyzeRecordsFixtureSlice({baselineAst:model.ast,currentAst:now.ast,selected:[{old:row,current:next}],implementationSources:['./sut.mjs']});});
 return{root,baseline,current,manifest,analysis,proof,cleanup:()=>fs.rmSync(root,{recursive:true,force:true})};
}
